BEGIN;SELECT plan(45);
INSERT INTO auth.users(id,email,raw_app_meta_data) VALUES('13900000-0000-4000-8000-000000000001','expense-correction@example.test','{"_invite_provisioned":true}'),('13900000-0000-4000-8000-000000000002','expense-other-maker@example.test','{"_invite_provisioned":true}');
CREATE TEMP TABLE exp139_company AS SELECT (public.provision_company_atomic('13900000-0000-4000-8000-000000000001','{"name":"Expense Correction Fixture","domain":"expense-correction.example.test","slug":"expense-correction"}')->>'id')::uuid id;
UPDATE public.users SET must_change_password=false WHERE auth_user_id='13900000-0000-4000-8000-000000000001';
INSERT INTO public.users(auth_user_id,tenant_id,email,role,status,must_change_password) SELECT '13900000-0000-4000-8000-000000000002',id,'expense-other-maker@example.test','general_manager','active',false FROM exp139_company;
CREATE TEMP TABLE exp139_cases(label text,id uuid DEFAULT gen_random_uuid(),request_uuid uuid DEFAULT gen_random_uuid(),result jsonb);
INSERT INTO exp139_cases(label) VALUES('edit'),('audit'),('approved'),('evidence'),('other maker');
GRANT SELECT ON exp139_company TO authenticated;GRANT SELECT,UPDATE ON exp139_cases TO authenticated;
INSERT INTO public.expenses(id,tenant_id,expense_type,amount,expense_date,vendor,receipt_url,created_by) SELECT c.id,t.id,'fuel',10,'2026-10-23','Original vendor','private-object-reference',CASE WHEN c.label='other maker' THEN '13900000-0000-4000-8000-000000000002'::uuid ELSE '13900000-0000-4000-8000-000000000001'::uuid END FROM exp139_cases c CROSS JOIN exp139_company t;
INSERT INTO auth.users(id,email,raw_app_meta_data) VALUES('13900000-0000-4000-8000-000000000003','expense-foreign@example.test','{"_invite_provisioned":true}');
CREATE TEMP TABLE exp139_foreign_company AS SELECT (public.provision_company_atomic('13900000-0000-4000-8000-000000000003','{"name":"Foreign Expense Fixture","domain":"expense-foreign.example.test","slug":"expense-foreign"}')->>'id')::uuid id;
INSERT INTO exp139_cases(label) VALUES('foreign');
INSERT INTO public.expenses(id,tenant_id,expense_type,amount,expense_date,created_by) SELECT c.id,t.id,'fuel',10,'2026-10-23','13900000-0000-4000-8000-000000000003' FROM exp139_cases c CROSS JOIN exp139_foreign_company t WHERE c.label='foreign';
CREATE TEMP TABLE exp139_details(data jsonb);INSERT INTO exp139_details VALUES('{"expense_type":"fuel","category":"Fuel","amount":12.34,"expense_date":"2026-10-23","vendor":"Edited vendor","description":"Reviewed correction","vat_rate":0}');GRANT SELECT ON exp139_details TO authenticated;
SELECT ok(NOT has_table_privilege('authenticated','public.expenses','UPDATE'),'Direct browser expense updates are denied');
SELECT ok(NOT has_function_privilege('anon','public.correct_pending_expense_atomic(uuid,integer,uuid,text,jsonb,text)','EXECUTE'),'Anonymous cannot correct pending expenses');
SELECT ok(NOT has_function_privilege('service_role','public.approve_expense_atomic(uuid,uuid,numeric,text,uuid)','EXECUTE'),'Legacy approval service grant is retired');
SELECT ok(NOT has_function_privilege('service_role','public.approve_expense_with_context_atomic(uuid,uuid,numeric,text,uuid,text,text)','EXECUTE'),'Legacy context approval service grant is retired');
SELECT ok(NOT has_function_privilege('service_role','public.reject_expense_atomic(uuid,uuid,text,uuid)','EXECUTE'),'Legacy rejection service grant is retired');
SET LOCAL ROLE service_role;
SELECT throws_ok($$SELECT public.approve_expense_atomic('13900000-0000-4000-8000-000000000001','13900000-0000-4000-8000-000000000001',15,'recoverable','13900000-0000-4000-8000-000000000001')$$,'42501',NULL,'Service cannot approve without reviewed source version');
SELECT throws_ok($$SELECT public.approve_expense_with_context_atomic('13900000-0000-4000-8000-000000000001','13900000-0000-4000-8000-000000000001',15,'recoverable','13900000-0000-4000-8000-000000000001','Review receipt','approvals_inbox')$$,'42501',NULL,'Service cannot bypass reviewed context approval');
SELECT throws_ok($$SELECT public.reject_expense_atomic('13900000-0000-4000-8000-000000000001','13900000-0000-4000-8000-000000000001','Reject receipt','13900000-0000-4000-8000-000000000001')$$,'42501',NULL,'Service cannot reject without reviewed source version');
RESET ROLE;
SET LOCAL ROLE authenticated;
SELECT set_config('request.jwt.claims','{"role":"authenticated","sub":"13900000-0000-4000-8000-000000000001","aal":"aal1"}',true);
SELECT throws_ok($$SELECT public.correct_pending_expense_atomic(c.id,1,c.request_uuid,'update',d.data,'Maker corrected the pending receipt') FROM exp139_cases c CROSS JOIN exp139_details d WHERE label='edit'$$,'42501','EXP_EDIT_FORBIDDEN','Correction enforces MFA inside transaction');
SELECT set_config('request.jwt.claims','{"role":"authenticated","sub":"13900000-0000-4000-8000-000000000001","aal":"aal2"}',true);
SELECT throws_ok($$SELECT public.correct_pending_expense_atomic(c.id,1,c.request_uuid,'update',d.data,'Maker corrected the pending receipt') FROM exp139_cases c CROSS JOIN exp139_details d WHERE label='other maker'$$,'42501','EXP_EDIT_MAKER_REQUIRED','One approver cannot rewrite another maker pending expense');
SELECT throws_ok($$SELECT public.correct_pending_expense_atomic(c.id,1,c.request_uuid,'update',d.data,'Maker corrected the pending receipt') FROM exp139_cases c CROSS JOIN exp139_details d WHERE label='foreign'$$,'P0001','EXP001: expense not found','Foreign tenant IDs do not reveal or mutate expense records');
SELECT throws_ok($$SELECT public.correct_pending_expense_atomic(c.id,1,c.request_uuid,'update',d.data||'{"tenant_id":"forged"}','Maker corrected the pending receipt') FROM exp139_cases c CROSS JOIN exp139_details d WHERE label='edit'$$,'22023','EXP_EDIT_INPUT','Browser cannot inject tenant, receipt or approval fields');
SELECT lives_ok($$UPDATE exp139_cases c SET result=public.correct_pending_expense_atomic(c.id,1,c.request_uuid,'update',d.data,'Maker corrected the pending receipt') FROM exp139_details d WHERE c.label='edit'$$,'Maker edit and audit commit atomically');
SELECT is((SELECT amount FROM public.expenses WHERE id=(SELECT id FROM exp139_cases WHERE label='edit')),12.34::numeric,'Exact edited amount is retained');
SELECT is((SELECT vat_rate FROM public.expenses WHERE id=(SELECT id FROM exp139_cases WHERE label='edit')),0::numeric,'Explicit zero VAT rate is preserved');
SELECT is((SELECT receipt_url FROM public.expenses WHERE id=(SELECT id FROM exp139_cases WHERE label='edit')),'private-object-reference','Edit retains existing receipt attachment');
SELECT is((SELECT correction_version FROM public.expenses WHERE id=(SELECT id FROM exp139_cases WHERE label='edit')),2,'Edit increments reviewed version once');
SELECT is((SELECT count(*)::integer FROM public.audit_log WHERE entity_id=(SELECT id FROM exp139_cases WHERE label='edit') AND action='expense_pending_updated'),1,'Edit retains one audit');
SELECT is((SELECT (public.correct_pending_expense_atomic(c.id,1,c.request_uuid,'update',d.data,'Maker corrected the pending receipt')->>'replayed')::boolean FROM exp139_cases c CROSS JOIN exp139_details d WHERE label='edit'),true,'Lost response safely replays the exact same edit');
SELECT is((SELECT count(*)::integer FROM public.audit_log WHERE entity_id=(SELECT id FROM exp139_cases WHERE label='edit') AND action='expense_pending_updated'),1,'Edit replay cannot duplicate audit or mutate twice');
SELECT throws_ok($$SELECT public.correct_pending_expense_atomic(c.id,1,c.request_uuid,'update',d.data||'{"amount":15}','Maker corrected the pending receipt') FROM exp139_cases c CROSS JOIN exp139_details d WHERE label='edit'$$,'P0001','EXP_EDIT_RETRY_MISMATCH','A request cannot silently save different details');
SELECT throws_ok($$SELECT public.correct_pending_expense_atomic(c.id,1,gen_random_uuid(),'update',d.data,'Maker corrected the pending receipt') FROM exp139_cases c CROSS JOIN exp139_details d WHERE label='edit'$$,'P0001','EXP_EDIT_STALE','Competing stale edit cannot overwrite newer values');
SELECT throws_ok($$SELECT public.decide_expense_reviewed_atomic((SELECT id FROM exp139_cases WHERE label='edit'),1,'approved',15,'recoverable',NULL,'expenses')$$,'P0001','EXP_EDIT_STALE','Approval cannot approve edited amounts from a stale dialog');
SELECT is((SELECT count(*)::integer FROM public.payables WHERE source_entity_id=(SELECT id FROM exp139_cases WHERE label='edit')),0,'Stale approval creates no payable');
SELECT throws_ok($$SELECT public.decide_expense_reviewed_atomic((SELECT id FROM exp139_cases WHERE label='edit'),1,'rejected',NULL,NULL,'Reject outdated evidence','approvals_inbox')$$,'P0001','EXP_EDIT_STALE','Rejection also requires the reviewed current version');
SELECT is((SELECT correction_version FROM public.fetch_pending_approvals((SELECT id FROM exp139_company),'expense',NULL,NULL,100) q CROSS JOIN LATERAL jsonb_to_record(q.subject_meta) m(correction_version integer) WHERE item_id=(SELECT id FROM exp139_cases WHERE label='edit')),2,'Approval queue exposes current expense review version');
SELECT lives_ok($$SELECT public.correct_pending_expense_atomic((SELECT id FROM exp139_cases WHERE label='edit'),2,'13900000-0000-4000-8000-000000000010','cancel',NULL,'Maker withdrew duplicate pending expense')$$,'Pending cancellation commits with reason and durable receipt');
SELECT ok((SELECT cancelled_at IS NOT NULL AND cancelled_by='13900000-0000-4000-8000-000000000001' AND cancellation_reason='Maker withdrew duplicate pending expense' AND NOT is_approved AND rejected_at IS NULL FROM public.expenses WHERE id=(SELECT id FROM exp139_cases WHERE label='edit')),'Cancellation is a distinct durable decision');
SELECT is((SELECT receipt_url FROM public.expenses WHERE id=(SELECT id FROM exp139_cases WHERE label='edit')),'private-object-reference','Cancellation retains receipt attachment and history');
SELECT is((public.correct_pending_expense_atomic((SELECT id FROM exp139_cases WHERE label='edit'),2,'13900000-0000-4000-8000-000000000010','cancel',NULL,'Maker withdrew duplicate pending expense')->>'replayed')::boolean,true,'Lost cancellation response safely replays');
SELECT is((SELECT count(*)::integer FROM public.audit_log WHERE entity_id=(SELECT id FROM exp139_cases WHERE label='edit') AND action='expense_cancelled'),1,'Cancellation replay cannot duplicate audit');
SELECT is((SELECT count(*)::integer FROM public.fetch_pending_approvals((SELECT id FROM exp139_company),'expense',NULL,NULL,100) WHERE item_id=(SELECT id FROM exp139_cases WHERE label='edit')),0,'Cancelled expense leaves pending approval queue');
SELECT throws_ok($$SELECT public.decide_expense_reviewed_atomic((SELECT id FROM exp139_cases WHERE label='edit'),3,'approved',15,'recoverable',NULL,'expenses')$$,'P0001','EXP_CANCELLED: expense was cancelled','Approval cannot race past committed cancellation');
SELECT throws_ok($$SELECT public.decide_expense_reviewed_atomic((SELECT id FROM exp139_cases WHERE label='edit'),3,'rejected',NULL,NULL,'Reject previously cancelled expense','approvals_inbox')$$,'P0001','EXP_CANCELLED: expense was cancelled','Rejection cannot rewrite cancellation');
RESET ROLE;
SELECT throws_ok($$SELECT public.approve_expense_atomic((SELECT id FROM exp139_company),(SELECT id FROM exp139_cases WHERE label='edit'),15,'recoverable','13900000-0000-4000-8000-000000000001')$$,'P0001','EXP_CANCELLED: expense was cancelled','Internal approval helper also cannot rewrite cancellation');
SELECT is((SELECT count(*)::integer FROM public.financial_events WHERE source_id=(SELECT id FROM exp139_cases WHERE label='edit')),0,'Failed cancelled approval creates no accounting event');
CREATE FUNCTION pg_temp.exp139_fail_audit() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF NEW.entity_id=(SELECT id FROM exp139_cases WHERE label='audit') AND NEW.action='expense_pending_updated' THEN RAISE EXCEPTION 'synthetic expense correction audit fault'; END IF;RETURN NEW;END $$;
CREATE TRIGGER exp139_audit_fault BEFORE INSERT ON public.audit_log FOR EACH ROW EXECUTE FUNCTION pg_temp.exp139_fail_audit();
SET LOCAL ROLE authenticated;
SELECT throws_ok($$SELECT public.correct_pending_expense_atomic(c.id,1,c.request_uuid,'update',d.data,'Maker corrected the pending receipt') FROM exp139_cases c CROSS JOIN exp139_details d WHERE label='audit'$$,'P0001','synthetic expense correction audit fault','Audit failure rolls back the whole edit');
SELECT is((SELECT amount FROM public.expenses WHERE id=(SELECT id FROM exp139_cases WHERE label='audit')),10::numeric,'Audit rollback retains original amount');
SELECT is((SELECT correction_version FROM public.expenses WHERE id=(SELECT id FROM exp139_cases WHERE label='audit')),1,'Audit rollback retains original version');
RESET ROLE;
SELECT is((SELECT count(*)::integer FROM public.expense_correction_receipts WHERE expense_id=(SELECT id FROM exp139_cases WHERE label='audit')),0,'Audit rollback retains no false retry receipt');
DROP TRIGGER exp139_audit_fault ON public.audit_log;
SET LOCAL ROLE authenticated;
SELECT lives_ok($$SELECT public.correct_pending_expense_atomic(c.id,1,c.request_uuid,'update',d.data,'Maker corrected the pending receipt') FROM exp139_cases c CROSS JOIN exp139_details d WHERE label='audit'$$,'Same edit can retry after transactional audit rollback');
SELECT lives_ok($$SELECT public.decide_expense_reviewed_atomic((SELECT id FROM exp139_cases WHERE label='approved'),1,'approved',15,'recoverable',NULL,'expenses')$$,'Reviewed approval keeps existing payable/event transaction');
SELECT throws_ok($$SELECT public.correct_pending_expense_atomic(c.id,1,c.request_uuid,'update',d.data,'Maker corrected the pending receipt') FROM exp139_cases c CROSS JOIN exp139_details d WHERE label='approved'$$,'P0001','EXP_EDIT_DECIDED','Maker cannot alter a decided expense');
RESET ROLE;
SELECT throws_ok($$UPDATE public.expenses SET amount=1 WHERE id=(SELECT id FROM exp139_cases WHERE label='approved')$$,'P0001','EXP_HISTORY_IMMUTABLE','Privileged direct edit cannot corrupt approved financial history');
INSERT INTO public.journal_entries(tenant_id,entry_date,entry_type,status,description_ar,source_module,source_entity_type,source_entity_id) SELECT t.id,CURRENT_DATE,'expense','draft','Imported evidence fixture','accounting','expense',c.id FROM exp139_company t CROSS JOIN exp139_cases c WHERE label='evidence';
SET LOCAL ROLE authenticated;
SELECT throws_ok($$SELECT public.correct_pending_expense_atomic(c.id,1,c.request_uuid,'update',d.data,'Maker corrected the pending receipt') FROM exp139_cases c CROSS JOIN exp139_details d WHERE label='evidence'$$,'P0001','EXP_EDIT_FINANCE_REVIEW','Imported accounting evidence requires explicit finance review');
SELECT * FROM finish();ROLLBACK;
